(()=>{const form=document.getElementById('register-form');if(!form){return;}const tabs=Array.from(document.querySelectorAll('.register-tabs .tabs__link'));const connectors=Array.from(document.querySelectorAll('.register-tabs .connector'));const steps=Array.from(form.querySelectorAll('[data-step]'));const prevButton=document.querySelector('[data-step-prev]');const nextButton=document.querySelector('[data-step-next]');const nextLabel=nextButton?.querySelector('[data-step-next-label]')?? null;const statusMessage=document.querySelector('[data-register-status]');const channelSelect=form.querySelector('[data-channel-select]');const channelTargets=Array.from(form.querySelectorAll('[data-channel-only]'));const toggleControls=Array.from(form.querySelectorAll('[data-toggle-control]'));const summaryTargets=Array.from(document.querySelectorAll('[data-summary-value]'));const summaryChannelElements=Array.from(document.querySelectorAll('[data-summary-channel]'));const summarySections=Array.from(document.querySelectorAll('[data-summary-section]'));const toggleInputs=new Map();let currentIndex=0;let maxVisitedIndex=0;form.querySelectorAll('[data-summary-toggle]').forEach((input)=>{if(input instanceof HTMLInputElement || input instanceof HTMLSelectElement){toggleInputs.set(input.dataset.summaryToggle ?? '',input);}});const stepLabels ={default: nextButton?.dataset.stepDefaultLabel ?? 'Siguiente',review: nextButton?.dataset.stepReviewLabel ?? 'Revisar',final: nextButton?.dataset.stepFinalLabel ?? 'Finalizar',};const messages ={terms: nextButton?.dataset.stepTermsMessage ?? '',success: nextButton?.dataset.stepSuccessMessage ?? '',};function setStatus(message=''){if(statusMessage){statusMessage.textContent=message;}}function readFieldValue(field){if(!field){return '';}if(field instanceof HTMLInputElement){if(field.type ==='checkbox'){if(field.dataset.summaryChecked && field.dataset.summaryUnchecked){return field.checked?field.dataset.summaryChecked:field.dataset.summaryUnchecked;}return field.checked?'Sí':'No';}if(field.type ==='file'){if(field.files && field.files.length > 0){return field.files[0].name;}return '';}return field.value.trim();}if(field instanceof HTMLSelectElement){const option=field.options[field.selectedIndex];return option?option.text.trim(): '';}return field.value?.trim?.()?? '';}function updateSummary(){summaryTargets.forEach((target)=>{const key=target.dataset.summaryValue ?? '';const field=form.querySelector(`[data-summary-field="${key}"]`);const value=readFieldValue(field);const fallback=target.dataset.summaryEmpty ?? '—';target.textContent=value || fallback;});const channelValue=channelSelect?.value ?? '';summaryChannelElements.forEach((element)=>{const allowed=(element.dataset.summaryChannel || '').split(',').map((item)=> item.trim()).filter(Boolean);const shouldShow=allowed.length ===0 || allowed.includes(channelValue);element.classList.toggle('is-hidden',!shouldShow);element.toggleAttribute('hidden',!shouldShow);});summarySections.forEach((section)=>{const toggleKey=section.dataset.summarySection ?? '';const control=toggleInputs.get(toggleKey);const shouldShow=control?control.checked:true;section.classList.toggle('is-hidden',!shouldShow);section.toggleAttribute('hidden',!shouldShow);});}function updateChannelVisibility(){const value=channelSelect?.value ?? '';channelTargets.forEach((element)=>{const allowed=(element.dataset.channelOnly || '').split(',').map((item)=> item.trim()).filter(Boolean);const visible=allowed.length ===0 || allowed.includes(value);element.classList.toggle('is-hidden',!visible);element.toggleAttribute('hidden',!visible);if(!visible){const inputs=element.querySelectorAll('input,select,textarea');inputs.forEach((input)=>{if(input instanceof HTMLInputElement){if(input.type ==='checkbox' || input.type ==='radio'){input.checked=false;}else if(input.type ==='file'){input.value='';}else{input.value='';}}else if(input instanceof HTMLSelectElement){input.selectedIndex=0;}else if(input instanceof HTMLTextAreaElement){input.value='';}});}});updateSummary();}function updateToggle(control){const key=control.dataset.toggleControl ?? '';const targets=form.querySelectorAll(`[data-toggle-target="${key}"]`);targets.forEach((target)=>{target.toggleAttribute('hidden',!control.checked);});updateSummary();}function updateTabs(){steps.forEach((step,index)=>{const isActive=index ===currentIndex;step.classList.toggle('form__tab-content--active',isActive);step.toggleAttribute('hidden',!isActive);});tabs.forEach((tab,index)=>{const isActive=index ===currentIndex;tab.classList.toggle('active',isActive);tab.classList.toggle('completed',index < currentIndex);tab.setAttribute('aria-current',isActive?'step':'false');});connectors.forEach((connector,index)=>{connector.classList.toggle('is-active',index < currentIndex);});if(prevButton){prevButton.disabled=currentIndex ===0;}if(nextLabel){let label=stepLabels.default;if(currentIndex ===steps.length - 1){label=stepLabels.final;}else if(currentIndex ===steps.length - 2){label=stepLabels.review;}nextLabel.textContent=label;}setStatus('');updateSummary();}function goTo(index){if(index < 0 || index >=steps.length || index ===currentIndex){return;}currentIndex=index;maxVisitedIndex=Math.max(maxVisitedIndex,index);updateTabs();}function nextStep(){if(!nextButton){return;}if(currentIndex ===steps.length - 1){const terms=form.querySelector('#register_terms');if(terms instanceof HTMLInputElement && !terms.checked){setStatus(messages.terms);terms.focus();return;}setStatus(messages.success);return;}goTo(currentIndex + 1);}function prevStep(){if(currentIndex ===0){return;}goTo(currentIndex - 1);}tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>{maxVisitedIndex=Math.max(maxVisitedIndex,index);goTo(index);});});if(prevButton){prevButton.addEventListener('click',prevStep);}if(nextButton){nextButton.addEventListener('click',nextStep);}if(channelSelect){channelSelect.addEventListener('change',updateChannelVisibility);}toggleControls.forEach((control)=>{if(control instanceof HTMLInputElement){control.addEventListener('change',()=> updateToggle(control));updateToggle(control);}});const summaryFields=Array.from(form.querySelectorAll('[data-summary-field]'));summaryFields.forEach((field)=>{const events=field instanceof HTMLInputElement &&(field.type ==='checkbox' || field.type ==='file')? ['change']:['input','change'];events.forEach((eventName)=>{field.addEventListener(eventName,updateSummary);});});updateChannelVisibility();updateTabs();})();